class ConfigList(GenericRtg):
    """Configlist command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Configlist command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ConfigList, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options

    def is_failure_indication(self, line, is_full_line):
        """
        Check if command failed. Do not treat 'executor.log_level : ERROR' as command failure.

        :param line: ine to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: False if line does not match regex with failure, True if line matches the failure regex.
        """
        match = self._regex_helper.search_compiled(self.re_fail, line)
        if match:
            return False if 'log_level' in line else True
        return False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "config list"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_head(line)
                self._parse_entry_with_number(line)
                self._parse_entry_without_number(line)
            except ParsingDone:
                pass
        return super(ConfigList, self).on_new_line(line, is_full_line)

    # Example line: EXECUTOR_STARTUP_TIME               : Tue Jun 18 11:04:01 CEST 2019
    _re_head = re.compile(r"^(?P<KEY>\w*)\s*:\s+(?P<VALUE>.*)")

    def _parse_head(self, line):
        """
        Parse one of the three lines at the head of command output.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_head, line):
            self.current_ret[self._regex_helper.group('KEY')] = self._regex_helper.group('VALUE')
            raise ParsingDone

    # Example line: ctrl_1.password                     : oZPS0POrRieRtu
    _re_entry_with_number = re.compile(r"(?P<SECTION>.*)_(?P<NUMBER>\d+)\.(?P<KEY>\w*)\s*:\s+(?P<VALUE>.*)")

    def _parse_entry_with_number(self, line):
        """
        Parse line contains entry with number in section name.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_entry_with_number, line):
            self.current_ret.setdefault(self._regex_helper.group('SECTION'), {}) \
                .setdefault(self._regex_helper.group('NUMBER'), {})[self._regex_helper.group('KEY')] = \
                convert_to_number(self._regex_helper.group('VALUE'))
            raise ParsingDone

    # Example line: executor.ue_config_url              : file:///usr/rtg/etc/ue.db
    _re_entry_without_number = re.compile(r"(?P<SECTION>.*[^\d])\.(?P<KEY>.*?)\s*:\s+(?P<VALUE>.*)")

    def _parse_entry_without_number(self, line):
        """
        Parse line contains entry without number in section name.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_entry_without_number, line):
            self.current_ret.setdefault(self._regex_helper.group('SECTION'), {})[self._regex_helper.group('KEY')] = \
                convert_to_number(self._regex_helper.group('VALUE'))
            raise ParsingDone


